      "analysisMechanism": "Mức lãi suất ưu đãi cố định từ 8,9%/năm áp dụng trong 6 tháng đầu. Điểm đột phá là VIB cam kết trần lãi suất thả nổi không vượt quá 15%/năm sau giai đoạn ưu đãi. Hạn mức vay lên đến 85% giá trị xe (tối đa 5 tỷ đồng), thời hạn vay đến 96 tháng (xe dưới 9 chỗ) và 72 tháng (xe tải). Quy mô gói tín dụng đạt 5.000 tỷ đồng, triển khai đến hết 31/01/2027.",
