      "verificationStatus": "VERIFIED",
      "briefingContext": "Bài viết phân tích và so sánh số tiền lãi thực tế người gửi tiền nhận được khi gửi tiết kiệm 200 triệu đồng kỳ hạn 6 tháng tại các ngân hàng thương mại lớn.",
      "briefingFacts": "Với khoản tiền 200 triệu đồng gửi kỳ hạn 6 tháng, số tiền lãi thực nhận dao động từ 4,2 triệu đến 5,8 triệu đồng tùy thuộc vào mức lãi suất niêm yết (từ 4,2%/năm tại nhóm Big4 đến 5,5% - 5,8%/năm tại các ngân hàng tư nhân như SHB, HDBank, VPBank, ACB).",
      "briefingPerspective": "Tác giả bài báo đưa ra bảng so sánh chi tiết giúp khách hàng thấy rõ sự chênh lệch lợi nhuận giữa kênh gửi tại quầy và gửi tiết kiệm online (thường được cộng thêm 0,1% - 0,3%/năm lãi suất), khuyến khích xu hướng tiết kiệm không dùng tiền mặt.",
      "briefingImplication": "Người gửi tiền có nguồn vốn nhàn rỗi ngắn hạn nên ưu tiên kênh gửi trực tuyến trên ứng dụng ngân hàng để tối ưu hóa tiền lãi và linh hoạt tất toán khi cần.",
      "fintechRelevance": "Các ngân hàng tích hợp tính năng gửi tiết kiệm tích lũy và ví sinh lời tự động ngay trên ứng dụng ngân hàng di động."
