      "briefingContext": "Báo cáo phân tích chuyên sâu về sự dịch chuyển vốn hóa và cuộc đua định giá giữa ngân hàng quốc doanh Vietcombank và khối ngân hàng tư nhân trong 6 năm qua.",
      "briefingFacts": "Trong giai đoạn 6 năm, vốn hóa thị trường của Vietcombank (VCB) hầu như đi ngang hoặc sụt giảm nhẹ về tỷ trọng so với toàn ngành. Trong khi đó, các ngân hàng tư nhân như Techcombank và VPBank tăng tốc quy mô vốn chủ sở hữu, khiến khoảng cách giá trị thị trường bị thu hẹp đáng kể.",
