      "briefingImplication": "Nhà đầu tư theo dõi kế hoạch phát hành riêng lẻ cho nhà đầu tư chiến lược nước ngoài của Vietcombank để đón đầu các đợt tái định giá cổ phiếu trong chu kỳ tới.",
      "fintechRelevance": "Phân tích cấu trúc vốn và định giá cổ phiếu ngân hàng — Không áp dụng giải pháp thanh toán bán lẻ."
